  "Une activité ne peut être attribuée automatiquement que si un seul bloc correspond à son outil, sa ressource et son unité. Les cas ambigus restent à choisir.": "Деятельность может быть автоматически назначена только тогда, когда именно один блок соответствует своему инструменту, ресурсу и единице. Вы можете выбрать двусмысленные совпадения.",
