  "Copier les puzzles Storm manqués": "Копировать неудавшиеся шахматные головоломки Сторм",
  "Classique : dès une erreur ou une aide. Storm : après une mauvaise réponse.": "Классический: после ошибки или помощи. После неправильного ответа.",
  "Les copies existantes et leurs annotations sont conservées, sans doublon dans la même base. Les anciennes tentatives ne sont pas copiées rétroactivement.": "Существующие копии и аннотации сохраняются без дубликатов в той же базе данных. Прошлые попытки не копируются ретроактивно.",
  "La solution du puzzle est indisponible. Recharge la page.": "Решение шахматной головоломки недоступно. Перезагрузить страницу.",
  "Puzzles à revoir": "Шахматные головоломки для рассмотрения",
  "Exercice ajouté à la base. Le puzzle est conservé.": "Упражнения, добавленные в базу данных. Ваша шахматная головоломка сохранена.",
  "La solution est préremplie. Tu peux la modifier ou ajouter des variantes.": "Раствор заполнен. Вы можете редактировать или добавить варианты.",
  "Revoir les puzzles joués": "Обзор играл шахматные головоломки",
  "La solution fournie pour cet exercice est invalide.": "Предлагаемое упражнение является недействительным.",
  "La solution ne commence pas à la position choisie.": "Решение не начинается в выбранном положении.",
  "Dès une erreur, un indice ou une solution affichée, le puzzle est ajouté à la base choisie. Cela s’applique aussi au puzzle classique en cours.": "После ошибки, намека или раскрытого решения шахматная головоломка добавляется в выбранную вами базу данных. Это также относится к современной классической шахматной головоломке.",
  "Crée d’abord une base d’étude dans la bibliothèque.": "Сначала создавайте базу данных исследований в библиотеке.",
  "Les copies existantes et leurs annotations sont conservées. L’historique et Puzzle Storm ne sont pas copiés automatiquement.": "Сохранились существующие копии и аннотации. Прошлые попытки и шахматные головоломки Storm не копируются автоматически.",
  "Réglages des puzzles enregistrés.": "Сохранились настройки шахматной головоломки.",
  "Déjà copié dans la bibliothèque.": "Уже копировано в библиотеку.",
