  "La sélection de puzzles prend trop de temps. Réessaie ou précise les filtres.": "Выбор шахматных головоломки занимает слишком много времени. Попробуйте еще раз или сократите фильтры.",
  "La solution de ce puzzle est invalide. Choisis un autre puzzle.": "Эта шахматная головоломка имеет недействительное решение. Выберите другую шахматную головоломку.",
