  "Un point par puzzle. Les bons coups prolongent le chrono; une erreur retire 10 secondes et remet le combo à zéro.": "Один балл за шахматную головоломку. Правильные шахматные движения продлевают время; ошибка вычитает 10 секунд и перезагружает комбинацию.",
