  "La partie reste inchangée dans la base jusqu’à Sauvegarder.": "Игра в шахматы в базе данных остается неизменной до тех пор, пока вы не нажмете на кнопку Сохранить.",
  "Annotation appliquée au brouillon. Sauvegarde la partie pour la conserver dans la base.": "Аннотация к проекту. Сохраните шахматную игру, чтобы сохранить ее в базе данных.",
  "Informations PGN appliquées au brouillon. Sauvegarde la partie pour les conserver dans la base.": "PGN информация, применяемая к проекту. Сохраните шахматную игру, чтобы сохранить ее в базе данных.",
  "Reprendre la séance en cours. Les modifications restent en brouillon tant que tu ne sauvegardes pas.": "Возобновите текущую сессию. Изменения остаются в проекте, пока вы не сэкономите.",
  "Préparation des statistiques exactes de cette position…": "Подготовить точные статистические данные для этой должности...",
  "Préparation des statistiques exactes de cette position. Elles apparaîtront automatiquement dès que le calcul sera terminé.": "Подготовить точные статистические данные для этой должности. Они появятся автоматически после завершения расчета.",
  "Ce calcul a dépassé le délai disponible. Réessaie dans un instant ou choisis une position plus avancée.": "Этот расчет превысил доступное время. Попробуйте еще раз или выберите позднее место.",
  "Statistiques exactes des parties importées. Les parties rejetées pendant l’importation sont exclues.": "Точные статистические данные для импортных игр в шахматы. игры в шахматы, отклоненные во время импорта, исключаются.",
  "Les résultats apparaîtront automatiquement dès qu’ils seront prêts.": "Результаты появятся автоматически, когда они будут готовы.",
  "La préparation continue sur le serveur. Clique sur Actualiser pour vérifier le résultat.": "Подготовка продолжается на сервере. Нажмите на обновление, чтобы проверить результат.",
  "Actualisation interrompue. Clique sur Actualiser pour réessayer.": "Перерыв освежения. Нажмите на Refresh, чтобы попробовать снова.",
  "Cette partie est trop longue pour être exportée depuis cet éditeur. Utilise l’export de la base.": "Эта шахматная игра слишком длинная, чтобы экспортировать из этого редактора. Используйте экспорт базы данных.",
