  "· filtres actifs": "· активные фильтры",
  "· toutes les parties": "· все шахматные игры",
  "Elo minimum · chaque joueur": "Минимум Elo · для каждого игрока",
  "Elo maximum · chaque joueur": "Максимально Elo · для каждого игрока",
  "Sans minimum": "Никакого минимума",
  "Cadences du PGN": "PGN Контроль времени",
  "Sans maximum": "Максимум",
  "Aucune coche = toutes les cadences, y compris les inconnues.": "Нет отбора = все временные элементы, включая неизвестные.",
  "L’Elo provient du PGN et doit respecter la plage pour les deux joueurs. Sans Elo, une partie est exclue si une borne est définie. Une cadence non renseignée ou non reconnue dans le PGN est « Inconnue ». Ces parties sont exclues si des cadences sont cochées, sauf si « Inconnue » est choisie.": "Elo происходит от PGN и должен быть в диапазоне для обоих игроков. шахматные игры без Elo исключаются при установлении границы. Отсутствующие или не признанные элементы управления PGN \"Неизвестны\". Эти шахматные игры исключаются при выборе контролей времени, если только не выбрано \"Неизвестно\".",
  ": indique un nombre valide pour la borne Elo.": ": введите действительный номер для линейки Elo.",
  ": choisis un Elo entier entre 0 et 4000, ou laisse la borne vide.": ": введите целое число Elo от 0 до 4000, или оставьте связанное пусто.",
  ": le minimum Elo ne peut pas dépasser le maximum.": ": минимум Elo не может превышать максимум Elo.",
  "Crée une base et importe des parties PGN dans la bibliothèque.": "Создайте базу данных и импортируйте PGN шахматные игры в библиотеку.",
  "Maîtres Lichess ne propose pas de filtre par Elo ou cadence. Pour filtrer une collection de maîtres, choisis une base importée comme Mega Database.": "У мастеров Lichess нет фильтров Elo или контроля времени. Для фильтрации мастер-коллекции выберите импортируемую базу данных, такую как Mega Database.",
  "Source principale": "Основной источник",
  "Mes bases PGN": "Мои базы данных PGN",
  "Seuls les coups joués de la ligne principale sont comptés. Les variantes d’analyse ne gonflent pas les statistiques.": "Считываются только основные шахматные шаги. Различия в анализе не увеличивают статистику.",
  "Référence dans chaque ligne": "Ссылка в каждом строке",
  "Comparer avec": "Сравните с",
  "Mes bases de référence": "Мои базовые данные",
  "Aucune référence": "Никаких ссылок",
  "Ces filtres sont indépendants de la base principale. Le pourcentage indique la fréquence du coup à cette position dans la référence choisie.": "Эти фильтры независимы от основной базы данных. Процент показывает частоту шаховных движений на этой позиции в выбранной ссылке.",
  "Probabilité de rencontre": "Вероятность встречи",
  "Afficher la probabilité de la ligne": "Показать вероятность линии",
  "Choisis ton camp directement dans l’explorateur. Seules les réponses adverses comptent ; tes coups sont supposés joués. Cette estimation suit la variante affichée et les filtres de la base sélectionnée. Pour un PGN démarrant sur un diagramme, elle est conditionnelle à ce départ.": "Выберите свою сторону прямо в исследователе. Считается только ответ соперника; ваши шахматные шаги предполагаются. Эта оценка следует за отображенной вариацией и выбранными фильтрами базы данных. Если PGN начинается с диаграммы, она зависит от этой исходной позиции.",
  "Mode d’analyse": "Режим анализа",
  "Rapide (~250 ms par coup)": "Быстрый (~ 250 мс за шаховный ход)",
  "Une profondeur plus élevée affine l’analyse et demande plus de temps. De 8 à 30, avec une limite de 10 secondes par coup. Si la cible n’est pas atteinte, ≈ signale l’évaluation obtenue ; sa profondeur réelle est visible au survol.": "Более высокая глубина усовершенствует анализ и занимает больше времени. От 8 до 30, с 10-секундным лимитом за шашки. Если цель не достигнута, ≈ отмечает результат.",
  "Chargement de la connexion…": "Загрузочная связь...",
