  "≈ 1 sur": "≈ 1 из",
  "Estimation selon la base, la cadence et le niveau sélectionnés. Seules les réponses adverses sont multipliées ; tes propres coups sont supposés joués.": "Оценка на основе выбранной базы данных, контроля времени и рейтинга. Только ответы противника умножаются; предполагаются ваши собственные шахматные шаги.",
