  ", dont des diagrammes": ", включая схемы",
  ". Chaque probabilité suppose son départ déjà atteint ; elles ne s’additionnent pas entre ces départs.": ". Каждая вероятность предполагает, что ее стартовая позиция достигнута; вероятности не могут быть добавлены по стартовым позициям.",
  "Ce répertoire commence sur un diagramme : les probabilités supposent cette position déjà atteinte.": "Этот открытый репертуар начинается с диаграммы: вероятности предполагают, что эта позиция уже достигнута.",
  "Aucune lacune trouvée dans les chemins examinés avec ces réglages.": "Никаких пробелов не было обнаружено в исследованных с помощью этих настроек путях.",
  "La limite de cette exploration est atteinte. Affine les réglages pour réduire le nombre de positions à examiner.": "Ограничение исследования было достигнуто. Усовершенствовать настройки, чтобы сократить количество позиций для изучения.",
  "Aucune lacune trouvée pour le moment. Poursuis l’exploration pour compléter le bilan.": "Пока нет пробелов. Продолжайте исследование, чтобы завершить отчет.",
  "Les données disponibles ne permettent pas encore de compléter le bilan. Ajuste les filtres ou réessaie plus tard.": "Доступные данные пока не могут завершить отчет. Настроить фильтры или попробуйте снова позже.",
