  "Nouvelle base de révision · Résoudre · Hybride. Toutes les variantes saisies seront acceptées comme solutions.": "Новая база данных · Solve · Hybrid. Все введенные вариации будут приняты в качестве решений.",
  "Position à jouer contre le moteur : les coups de solution sont facultatifs.": "Позиция для игры против шахматного двигателя: решения шахматные шаги являются необязательными.",
  "Position à jouer contre le moteur. Active les révisions dans les réglages de cette base pour la retrouver dans Révisions.": "Позиция для игры против шахматного двигателя. Включить отзывы в настройках этой базы данных, чтобы найти их в отзывах.",
  "Chaque décision de ton camp sera révisée séparément ; les variantes saisies fournissent les réponses acceptées.": "Каждое решение для вашей стороны рассматривается отдельно; введенные варианты дают принятые ответы.",
