  "Ces tranches sont propres à Lichess, sans équivalence directe avec les classements PGN ou Chess.com.": "Эти диапазоны являются специфическими для Lichess, без прямой эквивалентности рейтингам PGN или Chess.com.",
  "par coup. Flèches gauche et droite pour parcourir la partie.": "по шашкам. Используйте левые и правые стрелы для навигации в шахматной игре.",
