  "Deux versions de ton travail existent. Ouvre « Travail conservé » depuis le badge de l’analyse pour choisir celle à reprendre.": "Существуют две версии вашей работы. Откройте \"Сохраненная работа\" из значка анализа, чтобы выбрать, какую продолжить.",
  "Le stockage de cet appareil est indisponible ou plein. Ton travail reste en mémoire : sauvegarde le PGN avant de fermer.": "Хранение на этом устройстве недоступно или полно. Твоя работа все еще в памяти: сохрани PGN до закрытия.",
  "Le brouillon est conservé sur cet appareil, mais sa synchronisation est en attente.": "Проект сохранен на этом устройстве, но синхронизация ожидается.",
