  "Le brouillon est conservé en mémoire. Vérifier sa sauvegarde.": "Проект все еще в памяти. Проверьте, что он сохранен.",
  "Brouillon synchronisé sur ton compte; Sauvegarder l’inscrit dans le PGN.": "Проект синхронизируется с вашим аккаунтом; Save записывает его на PGN.",
  "Brouillon conservé sur cet appareil; Sauvegarder l’inscrit dans le PGN.": "Проект, сохраненный на этом устройстве, записывается на PGN.",
