  "La partie a changé dans la base. Ton brouillon est conservé; enregistre une copie ou recharge la partie avant de modifier la version de la base.": "Игра в шахматы изменилась в базе. Ваш проект сохранен; сохраните копию или перезагрузите шахматную игру перед редактированием версии базы данных.",
  "La partie source a été supprimée. Ton brouillon reste disponible pour en sauvegarder une copie.": "Источник шахматной игры был удален. Ваш проект все еще доступен для сохранения в копии.",
