  "Cette base sert de référence à l’explorer et à la recherche de positions. Pour travailler une partie ou la réviser, ouvre-la dans l’analyse et sauvegarde une copie dans une base personnelle.": "Эта база данных является справочником для исследователя и поиска позиций. Чтобы изучить или пересмотреть шахматную игру, открыть ее в анализе и сохранить копию в личной базе данных.",
  "Fichier source": "Источник файла",
  "Fichier importé sur la machine hébergeant Chess Gym.": "Файл, импортированный на компьютере хостинга Chess Gym.",
  "La sauvegarde complète inclut les parties de référence importées. Conserve aussi le fichier source pour pouvoir poursuivre une importation.": "Полное резервное обеспечение включает в себя импортные референтные шахматные игры. Также сохраните исходный файл для возобновления импорта.",
  "Enregistrer les réglages": "Сохранить настройки",
  "Retirer cette base": "Удалить эту базу данных",
  "Les modifications sont enregistrées, mais la liste n’a pas pu être actualisée. Recharge la base pour la mettre à jour. ": "Изменения сохранены, но список не может быть обновлен. Перезагрузить базу данных для обновления. ",
  "La partie a été supprimée de la base. Son analyse ouverte est conservée comme copie libre.": "Игра в шахматы была удалена из базы данных. Его открытый анализ хранится в виде бесплатного экземпляра.",
  "Les informations PGN sont enregistrées. Rouvre la partie pour actualiser les temps des coups. ": "Сохраняется информация PGN. Возобновить шахматную игру, чтобы обновить время движения шахмат. ",
