  "Les coups d’ouverture sont évalués individuellement. Les positions à résoudre ou à jouer ont leur propre historique.": "Открытие шахматных шагов оценивается индивидуально. Позиции для решения или игры имеют свою историю.",
  "Priorité des coups d’ouverture": "Открытие шахов приоритетный ход",
  "Fréquence de rencontre": "Частота встреч",
  "Ordre des échéances": "Порядок исполнения",
  "La fréquence utilise la dernière exploration « À compléter » de ce répertoire. Les reprises et les anciens retards restent prioritaires. Sans statistiques, l’ordre habituel est conservé.": "Frequency использует новейший сканер \"Coverage gaps\" в этом открывающемся репертуаре. Переоценка и более старые просроченные карты остаются приоритетом. Без статистики обычный порядок сохраняется.",
