  "La force 0–20 est le réglage du moteur, sans équivalence Elo annoncée. L’analyse reste à pleine force.": "Умение 0-20 - это настройка шахматного двигателя, без претензий на эквивалентность Elo. Анализ всегда использует полную силу.",
  "Espacement et charge de travail": "Расстояние и рабочая нагрузка",
  "L’espacement est adaptatif : chaque réussite allonge le délai de la carte. Les valeurs ci-dessous sont les délais minimaux, avec un plafond pour les reprises.": "Расстояние адаптивное: каждый успех увеличивает интервал карты. Нижеприведенные значения представляют собой минимальные интервалы, с максимальным для будущих пересмотров.",
