  "Cette partie a été déplacée. Rouvre sa base pour actualiser la liste.": "Эта шахматная игра была перенесена. Откройте базу данных, чтобы обновлять список.",
  "La position de cet exercice a changé. La partie complète est ouverte à son point de départ.": "Позиция этого упражнения изменилась. Полная игра в шахматы открыта в стартовом положении.",
  "La séance de révision n’est plus active.": "Сессия обзора больше не действует.",
  "Sauvegardes": "Резервные копии",
  "La sauvegarde personnelle contient tes bases de travail, annotations, réglages, brouillons et historique de révision. Elle exclut les grandes bases de référence.": "Персональная резервная запись содержит базы данных исследования, комментарии, настройки, чертежи и историю обзора. Он исключает большие справочные базы данных.",
  "Ce serveur propose la sauvegarde complète, qui contient également les grandes bases de référence.": "Этот сервер обеспечивает полную резервную копию, которая также содержит большие справочные базы данных.",
  "Sauvegarde personnelle": "Личная поддержка",
  "Sauvegarde complète": "Полное подкрепление",
