  "Processus d’importation": "Импортные процессы",
  "Le budget est partagé entre les imports et les deux moteurs : analyse interactive et tâches de fond. Les changements s’appliquent aux prochains calculs et aux prochains imports; un import déjà lancé conserve ses ressources.": "Бюджет делится между импортами и двумя шахматными двигателями: интерактивным анализом и фоновой работой. Изменения распространяются на предстоящие расчеты и импорт; активный импорт сохраняет свои ресурсы.",
  "Configuration active : {threads} cœur(s) et {memory} Mo par moteur; {workers} processus d’importation.": "Активная конфигурация: {threads} thread (s) и {memory} MB на шахматный двигатель; {workers} импортные процессы.",
  "Le nouveau profil attend la fin des calculs et de l’import en cours.": "Новый профиль будет применяться при активных расчетах и завершении импорта.",
  "Enregistrer la performance": "Сохранить настройки производительности",
  "Les sauvegardes personnelles comprennent les parties, annotations, réglages, brouillons et progrès. Les grandes références restent séparées.": "Личные резервные копии содержат шахматные игры, комментарии, настройки, чертежи и прогресс. Большие справочные базы данных остаются отдельными.",
  "Sauvegardes automatiques": "Автоматические резервные копии",
  "Fréquence (heures)": "Частота (часы)",
  "Copies automatiques à conserver": "Автоматические копии для хранения",
  "Dossier sur le serveur": "Папка на сервере",
  "Seules les anciennes copies automatiques de ChessGym sont retirées. Les sauvegardes créées manuellement restent conservées.": "Сняты только старые автоматические копии ChessGym. Ручно созданные резервные копии хранятся.",
  "Enregistrer les sauvegardes": "Сохранять настройки резервного копирования",
  "Créer une copie maintenant": "Создайте резервную копию сейчас",
  "Télécharger les données personnelles": "Загрузка персональных данных",
