  "Sauvegarde créée et vérifiée.": "Запись создана и подтверждена.",
  "Cette copie inclut toutes les grandes références et peut être très volumineuse.": "Эта копия включает в себя все большие базовые данные и может быть очень большой.",
  "Télécharger": "Скачать",
  "Restaurer les données personnelles": "Восстановление персональных данных",
  "Vérifie la sauvegarde souhaitée dans la liste ci-dessous.": "Проверьте нужную резервную копию в списке ниже.",
  "Arrête ChessGym.": "Остановите ChessGym.",
  "Dans le dossier de ChessGym, ouvre « Restaurer ChessGym.cmd » et choisis ton archive.": "В папке ChessGym откройте \"Restaurer ChessGym.cmd\" и выберите свой архив.",
  "Relance ChessGym et reconnecte-toi.": "Начните ChessGym снова и подпишитесь.",
  "La restauration conserve une copie de sécurité des données actuelles. Les fichiers des grandes références restent en place; sur un autre serveur, ils doivent être transférés séparément.": "Восстановление сохраняет копию текущих данных. Большие справочные файлы остаются на месте; на другом сервере они должны быть переданы отдельно.",
