  "La durée est un objectif de temps actif. Tu peux terminer la carte en cours, faire une pause et reprendre plus tard.": "Продолжительность является активной целью исследования. Вы можете закончить текущую карту, сделать паузу и продолжить позже.",
  "Bases incluses": "Включенные базы данных",
  "Active les révisions dans les réglages d’une base pour préparer ta séance.": "Включить обзоры в настройках базы данных для подготовки сессии.",
  "Actualiser l’aperçu": "Просмотр обновления",
  "Commencer la séance": "Начало сессии",
  "Composition de la séance": "Состав сессии",
  "Composition proposée": "Предлагаемая сессия",
  "{count} exercices pour cette séance": "{count} упражнения для этой сессии",
  "Les erreurs personnelles et puzzles échoués proviennent des exercices déjà présents dans tes bases actives. Les paramètres et limites de chaque base sont conservés.": "Личные ошибки и неудачные шахматные головоломки происходят из упражнений, которые уже есть в ваших активных базах данных. Каждая база данных сохраняет свои настройки и ограничения.",
  "Actualise l’aperçu pour vérifier cette sélection.": "Обновите просмотр, чтобы проверить этот выбор.",
  "Préparation de l’aperçu…": "Подготавливаю предварительное...",
  "La séance respecte les échéances et les limites quotidiennes.": "На заседании соблюдаются сроки и ежедневные ограничения.",
  "Aucun exercice disponible pour cette sélection aujourd’hui.": "На сегодняшний день нет никаких упражнений для этого отбора.",
  "Préparation de la séance…": "Подготовительная сессия...",
  "Vérifier et reprendre": "Проверка и резюме",
  "La création de la séance est en attente de confirmation. Réessaie pour retrouver la même séance.": "Создание сессии ожидает подтверждения. Попробуйте восстановить ту же сессию.",
  "La séance est prête. Termine le coup en cours pour l’ouvrir.": "Заседание готово. Заверши текущий шаховный ход, чтобы открыть его.",
  "Mettre la séance en pause": "Сеанс паузы",
  "Conserver dans les appris avec des rappels d’entretien espacés": "Сохраняйте то, что вы узнали с расстоянием напоминания о обслуживании",
  "Marquer comme maîtrisé avec entretien des acquis": "Отметка, полученная при проверке технического обслуживания",
  "{count} exercices maîtrisés. Des rappels d’entretien espacés préservent ces acquis.": "{count} упражнения освоены. Разрывные обзоры технического обслуживания помогают сохранить их.",
  "Les prochaines reprises respectent les réglages de chaque base.": "Предстоящие обзоры уважают настройки каждой базы данных.",
  "Entretenir les cartes maîtrisées": "Сохраняйте мастерские карты",
  "Rappel d’entretien · jours": "Интервал обслуживания · день",
  "Maximum de rappels par jour": "Максимальные напоминания в день",
  "Les acquis restent conservés. Les premiers rappels des anciennes cartes sont répartis dans le temps, sous ce plafond quotidien. Une erreur remet la carte en apprentissage.": "Ваш прогресс сохранен. Первоначальные напоминания для существующих карт распространяются с течением времени в пределах этого ежедневного лимита. Ошибка возвращает карту к обучению.",
  "Les cartes au-delà de ce seuil deviennent maîtrisées. Leur historique est conservé et les rappels suivent les réglages d’entretien ci-dessous.": "Карты, выходящие за этот порог, становятся мастерскими. Их история сохранилась, и напоминания следуют настройкам обслуживания ниже.",
  "{count} rappels d’entretien dus": "{count} Проверка технического обслуживания",
  " cartes actives. Les rappels des cartes maîtrisées suivent tes réglages d’entretien. ": " активные карты. Примечания с мастер-картой следуют вашим настройкам обслуживания. ",
  "Aucun exercice disponible. Les cartes maîtrisées suivent leurs rappels d’entretien. Vérifie les parties sélectionnées et les réponses enregistrées dans cette base.": "Нет никаких упражнений. Мастер карты следуют своему графику обслуживания. Проверьте выбранные шахматные игры и сохраните ответы в этой базе данных.",
