  "Voir les données": "Посмотреть данные",
  "Durées enregistrées pour les activités sélectionnées": "Записанная длительность выбранных занятий",
  "Stockfish sert à l’analyse et au jeu classique; Maia reproduit un jeu humain. Les bases de référence et de puzzles restent facultatives.": "Stockfish используется для анализа и обычной игры; Maia имитирует человеческую игру. Справочные базы и базы задач необязательны.",
  "Quand ChessGym est ouvert, les versions compatibles des moteurs et les bases installées compatibles sont vérifiées puis actualisées. Les éditions Lumbra se téléchargent séparément sur leur site. Les téléchargements peuvent être volumineux.": "Пока ChessGym работает, совместимые движки и установленные базы проверяются и обновляются. Выпуски Lumbra скачиваются отдельно с их сайта. Загрузки могут быть большими.",
  "Licence : {license}": "Лицензия: {license}",
  "Conditions de licence": "Условия лицензии",
  "Par Michael Jansen. Usage non commercial avec attribution; une licence distincte est nécessaire pour un usage commercial.": "Автор: Michael Jansen. Некоммерческое использование с указанием авторства; для коммерческого использования требуется отдельная лицензия.",
  "Télécharge cette édition sur le site Lumbra, accepte sa licence, puis indique le fichier .7z ou .pgn présent sur le PC ou serveur de ChessGym.": "Скачайте этот выпуск с сайта Lumbra, примите условия лицензии, затем укажите файл .7z или .pgn на компьютере или сервере, где работает ChessGym.",
  "Télécharger sur Lumbra": "Скачать с Lumbra",
  "Chemin du fichier téléchargé sur le serveur": "Путь к скачанному файлу на сервере",
  "Ex. C:\\Téléchargements\\Lumbra.7z": "Например, C:\\Downloads\\Lumbra.7z",
  "Utiliser comme référence de maîtres": "Использовать как справочную базу мастеров",
  "Importer la base téléchargée": "Импортировать скачанную базу",
  "Les nouvelles éditions Lumbra se téléchargent sur leur site; les mises à jour automatiques ne les remplacent pas.": "Новые выпуски Lumbra скачиваются с их сайта; автоматические обновления их не заменяют.",
  "Taille de l’archive : environ {size} Mo": "Размер архива: около {size} МБ",
  "Indique le chemin du fichier Lumbra téléchargé.": "Укажите путь к скачанному файлу Lumbra.",
  "Lumbra OTB Elite — maîtres 2400+": "Lumbra OTB Elite — мастера 2400+",
  "Lumbra Gigabase OTB — complète": "Lumbra Gigabase OTB — полная",
  "Parties sur échiquier entre deux joueurs classés au moins 2400 Elo. Télécharge l’archive officielle, puis importe-la ici.": "Очные партии между игроками, каждый из которых имеет рейтинг не ниже 2400 Эло. Скачайте официальный архив и импортируйте его здесь.",
  "Collection complète des parties sur échiquier. L’import et l’indexation peuvent prendre plusieurs heures et beaucoup d’espace disque.": "Полная коллекция очных партий. Импорт и индексация могут занять несколько часов и потребовать много места на диске.",
  "Gratuit avec attribution pour un usage non commercial. Une licence distincte est nécessaire pour un usage commercial.": "Бесплатно для некоммерческого использования с указанием авторства. Для коммерческого использования требуется отдельная лицензия.",
  "Vérification et copie de l’archive Lumbra": "Проверка и копирование архива Lumbra",
